solution.code:
package solution

import "encoding/json"

type Config struct {
	Host   string `json:"host"`
	Port   int    `json:"port"`
	APIKey string `json:"api_key"`
}

func Parse(data []byte) (Config, error) {
	c := Config{Port: 8080} // default applied first
	// Unmarshal only overwrites keys present in the JSON, so an absent
	// "port" leaves the default 8080 untouched.
	if err := json.Unmarshal(data, &c); err != nil {
		return Config{}, err
	}
	return c, nil
}

codeLab.testHarness:
package solution

import "testing"

func TestParse(t *testing.T) {
	// port present -> overrides default
	c, err := Parse([]byte(`{"host":"db","port":5432,"api_key":"secret"}`))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if c.Host != "db" || c.Port != 5432 || c.APIKey != "secret" {
		t.Errorf("got %+v", c)
	}

	// port absent -> default 8080
	c2, err := Parse([]byte(`{"host":"web"}`))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if c2.Port != 8080 {
		t.Errorf("want default port 8080, got %d", c2.Port)
	}

	// invalid JSON -> error
	if _, err := Parse([]byte(`{bad`)); err == nil {
		t.Error("expected error for invalid JSON")
	}
}

