func DecodeStrict[T any](data []byte) (T, error) {
	var out T
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields() // reject unexpected keys
	if err := dec.Decode(&out); err != nil {
		var zero T
		return zero, fmt.Errorf("decode strict %T: %w", out, err)
	}
	return out, nil
}

type Money int64 // amount in cents

func (m Money) MarshalJSON() ([]byte, error) {
	neg := ""
	c := int64(m)
	if c < 0 { // handle negatives cleanly
		neg, c = "-", -c
	}
	// Build "D.CC" and wrap in quotes so it's a JSON string.
	s := fmt.Sprintf("\"%s%d.%02d\"", neg, c/100, c%100)
	return []byte(s), nil
}
